class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{int index=0;static final pages=<Widget>[const _Dashboard(),const StudyPlannerScreen(),const MentorScreen(),const ProgressScreen()];@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:pages[index]),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_rounded),label:'Home'),NavigationDestination(icon:Icon(Icons.menu_book_rounded),label:'Plan'),NavigationDestination(icon:Icon(Icons.auto_awesome_rounded),label:'Mentor'),NavigationDestination(icon:Icon(Icons.bar_chart_rounded),label:'Progress')]));}
class _Dashboard extends StatefulWidget{const _Dashboard();@override State<_Dashboard> createState()=>_DashboardState();}
class _DashboardState extends State<_Dashboard>{int accuracy=0,mistakes=0,mocks=0;String exam='Exam',priority='Take a diagnostic mock';@override void initState(){super.initState();load();}Future<void> load()async{final p=await SharedPreferences.getInstance();final c=p.getInt('last_mock_correct')??0,t=p.getInt('last_mock_total')??0;accuracy=t==0?0:(c/t*100).round();mistakes=(p.getStringList('mistake_book')??[]).length;mocks=p.getInt('mock_count')??0;exam=p.getString('exam')??'Exam';final weak=p.getStringList('detected_weak_subjects')??[];priority=t==0?'Take a diagnostic mock':accuracy<60?'Repair '+(weak.isEmpty?'accuracy':weak.first):accuracy<80?'Timed PYQ + mistake review':'Full mock + speed practice';if(mounted)setState((){});}
 @override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(20),children:[Text('AgenticAI V2',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800)),Text(exam+' • Adaptive preparation system'),const SizedBox(height:20),Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.auto_awesome_rounded,size:32),const SizedBox(height:10),Text("Today's Mission",style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(priority),const SizedBox(height:12),Text('Last accuracy '+accuracy.toString()+'% • '+mistakes.toString()+' mistakes to revise')]))),const SizedBox(height:14),Row(children:[Expanded(child:_Stat('Accuracy',accuracy.toString()+'%')),const SizedBox(width:10),Expanded(child:_Stat('Mocks',mocks.toString()))]),const SizedBox(height:14),const _Launch(Icons.psychology_alt_rounded,'Ask Agent','Performance-based next action',AgentActionScreen()),const SizedBox(height:10),const _Launch(Icons.quiz_rounded,'Adaptive Mock','Timer • -0.25 • auto weak detection',MockTestScreen()),const SizedBox(height:10),const _Launch(Icons.menu_book_rounded,'Mistake Book','Wrong/skipped questions saved automatically',MistakeBookScreen()),const SizedBox(height:10),const _Launch(Icons.school_rounded,'Exam Preparation','Subject → chapter → priority → progress',Scaffold(body:SafeArea(child:PreparationScreen()))),const SizedBox(height:10),const _Launch(Icons.public_rounded,'GK & Current Affairs','Revision tracker and saved areas',CurrentAffairsScreen())]));}
class _Stat extends StatelessWidget{final String a,b;const _Stat(this.a,this.b);@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(b,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),Text(a)])));}
class _Launch extends StatelessWidget{final IconData icon;final String title,sub;final Widget page;const _Launch(this.icon,this.title,this.sub,this.page);@override Widget build(BuildContext context)=>Card(child:ListTile(contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:8),leading:Icon(icon),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(sub),trailing:const Icon(Icons.chevron_right_rounded),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>page))));}
